// Normalizasyon yardimcilari (kaynak ve pazardan bagimsiz calisir)
// trSafe: normalises the dotted-capital-I / combining-dot trap in
// JS toLowerCase(), so the same title from two sources yields one key.
// ü/ö BILEREK dokunulmadi: mevcut Job_Posts satirlarinin dedup key'leri degismesin.
function trSafe(s) {
  return String(s || '')
    .replace(/İ/g, 'i')
    .toLowerCase()
    .replace(/\u0307/g, '')
    .replace(/ı/g, 'i')
    .replace(/ş/g, 's')
    .replace(/ğ/g, 'g')
    .replace(/ç/g, 'c');
}

// ESKI sirket normalizasyonu — SADECE gecis anahtarlari icin (asagidaki v2'ye bak).
function normalizeCompanyLegacy(s) {
  if (!s) return '';
  return trSafe(s)
    .replace(/\b(gmbh|ag|se|kg|co\.?|ltd|inc|llc|& co\.? kg|mbh|deutschland|holding|group|consulting)\b/g, '')
    .replace(/\b(a\.?s\.?|ltd\.?\s*sti\.?|sti\.?|anonim sirketi|limited sirketi)\b/g, '')
    .replace(/[^\w\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// v2 (2026-08-21): BOSLUK da atiliyor. Ayni sirket kaynaktan kaynaga farkli
// yaziliyor ("Freenow" / "FREE NOW", "Data One" / "DataOne") ve eski formul bunlari
// iki AYRI ilan sayip ikisini de Haiku'ya yolluyordu. Kabul edilen risk: adlari sadece
// bosluklariyla ayrilan iki gercek sirket tek sayilir — pratikte yok denecek kadar nadir.
function normalizeCompany(s) {
  return normalizeCompanyLegacy(s).replace(/\s+/g, '');
}

// v4 (2026-09-02): SIRKET KOKU. Ayni ilan farkli TUZEL KISILIK altinda geliyordu ve
// iki AYRI ilan sayiliyordu — tetikleyen vaka: "Data Scientist II, Music DISCO"
// LinkedIn'de "Amazon Music", Indeed'de "Amazon Deutschland Services GmbH" (ikisi de 89).
// v3 bunlari "amazonmusic" / "amazonservices" yapiyordu. v4 ILK ANLAMLI KELIMEYI alir.
//
// UC KORUMA — hepsi 5.095 gercek satirda olculdu (266 ek birlesme, YANLIS birlesme YOK):
//  1) AKSANLAR ONCE KATLANIR. Aksi halde `[^\w\s]` umlaut'u bosluga cevirip kelimeyi
//     boler: "Stroer SE" -> "str er" -> kok "str" olurdu. Once NFD ile katla.
//  2) AYIRT EDICI OLMAYAN ILK KELIME -> IKI KELIME AL. Yoksa "Deutsche Bahn" ve
//     "Deutsche Bank" ayni koke duserdi. Ayni sebeple Fraunhofer/Max Planck enstituleri.
//  3) KOK EN AZ 3 HARF. "R+V Versicherung" -> [r, v, ...] -> kok "r" olurdu ve tek
//     harfle baslayan her sirketle carpisirdi; 3 harfe tamamlaniyor ("rv").
const CO_SUFFIX = new Set(('gmbh mbh ag se kg kgaa ohg ug co ltd limited inc llc corp plc bv nv sa sarl spa oy ab ' +
  'holding holdings group gruppe konzern deutschland germany europe europa international global services service ' +
  'solutions technologies technology digital consulting ventures partners stiftung verwaltungs').split(' '));
const CO_GENERIC_FIRST = new Set(('deutsche deutscher deutsches die der das the neue neuer erste sued nord ost west ' +
  'bayerische berliner hamburger muenchner muenchener stadt universitaet universitat hochschule fraunhofer max ' +
  'leibniz helmholtz first new smart my your data tech digital next').split(' '));
function normalizeCompanyV4(s) {
  const base = trSafe(String(s || ''))
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/ß/g, 'ss')
    .replace(/[^\w\s]/g, ' ').replace(/\s+/g, ' ').trim();
  if (!base) return '';
  let toks = base.split(' ').filter(t => !CO_SUFFIX.has(t));
  if (!toks.length) toks = base.split(' ');
  let root = toks[0], k = 1;
  if (CO_GENERIC_FIRST.has(root) && toks[1]) { root += toks[1]; k = 2; }
  while (root.length < 3 && toks[k]) { root += toks[k]; k++; }
  return root;
}

// ESKI baslik normalizasyonu — SADECE gecis anahtarlari icin. Sheet'teki mevcut
// job_id'ler bununla uretildi; degistirirsek tum canli ilanlar "yeni" gorunur (dup dalgasi).
function normalizeTitleLegacy(s) {
  if (!s) return '';
  return trSafe(s)
    .replace(/\((m\/w\/d|f\/m\/d|w\/m\/d|m\/f\/d|d\/f\/m|m\/f\/x|w\/m\/x|all genders|gn|m\/w|d)\)/g, '')
    .replace(/\b(junior|jr\.?|entry level|associate)\b/g, '')
    .replace(/[^\w\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// v2 (2026-07-28): ayni ilan kaynaktan kaynaga farkli yaziliyordu ->
//   (a) YUMUSAK TIRE: bazi kaynaklar basliga U+00AD serpistiriyor ("Da\u00adta Ana\u00adlysts")
//   (b) BASTAKI SAYI SOZCUGU: "Zwei Data Analysts ..." vs "Data Analysts ..." (Bundesbank: 4 mektup)
function normalizeTitle(s) {
  if (!s) return '';
  return trSafe(s)
    .replace(/[\u00ad\u200b\u200c\u200d\ufeff]/g, '')
    .replace(/^(zwei|drei|vier|mehrere|two|three|several)\s+/, '')
    .replace(/\((m\/w\/d|f\/m\/d|w\/m\/d|m\/f\/d|d\/f\/m|m\/f\/x|w\/m\/x|all genders|gn|m\/w|d)\)/g, '')
    .replace(/\b(junior|jr\.?|entry level|associate)\b/g, '')
    .replace(/[^\w\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeCity(s) {
  if (!s) return '';
  return trSafe(s)
    .replace(/münchen/g, 'munich')
    .replace(/köln/g, 'cologne')
    .replace(/nürnberg/g, 'nuremberg')
    .replace(/\(kreis\)/g, '')
    .replace(/greater\s+\w+\s+area/g, '')
    .replace(/,.*$/, '')
    .replace(/[^\w\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}


// city bazen ham JSON blob'undan ({"raw":"Berlin, Germany","locality":"Berlin"}) turetiliyor:
// Fields node'lari location.split(',')[0] yapiyor ve `{"raw":"Berlin` gibi bir sey cikiyor.
// Ayni ilan StepStone'dan duz "Berlin" gelince FARKLI anahtar uretip MUKERRER satir olusuyordu.
function sadeCity(v) {
  const s = String(v || '').trim();
  if (!s.startsWith('{')) return s;
  try {
    const o = JSON.parse(s);
    return o.locality || o.raw || s;
  } catch (e) { return s; }
}

function hash(str) {
  let h = 0;
  for (let i = 0; i < str.length; i++) {
    h = ((h << 5) - h) + str.charCodeAt(i);
    h |= 0;
  }
  return Math.abs(h).toString(36);
}


// --- v3 (2026-08-26): SEHIR ARTIK BASLIK METNINDEN DE SILINIYOR ---------------
// Birincil anahtar zaten `city` ALANINI disliyordu, ama sehir cogu zaman BASLIGIN
// ICINDE geciyor ("Data Engineer in Berlin" / "... Berlin" / "... in Munchen"),
// bu yuzden ayni ilan 3 ayri anahtar uretiyordu. Olculdu (3.525 satirlik sheet):
// 36 kumede 60 mukerrer satir; ISR/Finanz Informatik gibi AYNI boilerplate'i
// paylasan FARKLI roller ise dokunulmadan kaliyor (over-merge yok).
const DE_CITIES = ['berlin','münchen','munchen','munich','hamburg','köln','koln','cologne','frankfurt',
 'frankfurt am main','stuttgart','düsseldorf','dusseldorf','dortmund','essen','leipzig','bremen','dresden',
 'hannover','nürnberg','nurnberg','nuremberg','duisburg','bochum','wuppertal','bielefeld','bonn','münster',
 'munster','karlsruhe','mannheim','augsburg','wiesbaden','mönchengladbach','gelsenkirchen','braunschweig',
 'chemnitz','kiel','aachen','halle','magdeburg','freiburg','krefeld','mainz','lübeck','lubeck','erfurt',
 'rostock','kassel','potsdam','saarbrücken','saarbrucken','hagen','heidelberg','darmstadt','regensburg',
 'ingolstadt','würzburg','wurzburg','ulm','heilbronn','pforzheim','göttingen','gottingen','koblenz','jena',
 'remote','deutschland','germany','homeoffice','home office'];

function escapeRx(s) { return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }

function normalizeTitleV3(s, city, company) {
  let t = normalizeTitle(s);                       // v2 ciktisi: kucuk harf, noktalama -> bosluk
  const co = normalizeCompanyLegacy(company);      // "... - PRODYNA SE" sonekini at
  if (co) t = t.replace(new RegExp('\\s+' + escapeRx(co) + '\\s*$', 'g'), ' ');
  const own = new Set();
  const rawC = trSafe(sadeCity(city)).replace(/[^\w\s]/g, ' ').replace(/\s+/g, ' ').trim();
  if (rawC) { own.add(rawC); own.add(rawC.split(' ')[0]); }
  const nc = normalizeCity(sadeCity(city));
  if (nc) { own.add(nc); own.add(nc.split(' ')[0]); }
  for (const c of [...own, ...DE_CITIES]) {
    if (!c || c.length < 3) continue;
    t = t.replace(new RegExp('\\b' + escapeRx(c) + '\\b', 'g'), ' ');
  }
  t = t.replace(/\b(in|im|at|bei|standort|standorte|raum|region|near|area|und|oder|or)\b/g, ' ')
       .replace(/\s+/g, ' ').trim();
  // Guvenlik: sehir/sirket silindikten sonra baslik bosaldiysa v2'ye geri don.
  return t || normalizeTitle(s);
}

const item = $input.item.json;

// Bu ilani hangi arama terimi buldu? n8n'in item eslestirmesi kaynaktan kaynaga
// farkli davranabilir, o yuzden PATLAMAYA IZIN VERMEYEN bir okuma yapiyoruz:
// eslestirme cozulemezse alan bos kalir, kosu devam eder.
let search_kw = '';
try { search_kw = $('Keywords DE').item.json.kw || ''; } catch (e) { search_kw = ''; }

// PRIMARY = CITY'SIZ (sehir YOK): ayni ilan farkli kaynaklardan farkli sehirle gelse bile
// (or. LinkedIn "Berlin" vs XING "Munchen") ayni anahtar uretir -> kaynaklar-arasi mukerrer BIRLESIR.
// Kabul edilen risk: ayni sirket ayni basligi 2 farkli sehirde GERCEKTEN 2 ayri ilan olarak acsa
// tek sayilir (dedup icin mantikli — ayni role bir kez basvurulur).
const citylessString = `${normalizeCompany(item.company)}__${normalizeTitle(item.title)}`;
// GECIS ANAHTARLARI: mevcut sheet job_id'leri city'li formulle yazildi (Write nodes: job_id = dedup_key).
// Filter New Ads bunlara da bakar ki formul degisimi tum canli ilanlari "yeni" gosterip dup dalgasi YARATMASIN.
// GECIS ANAHTARLARI **ESKI** baslik normalizasyonuyla uretilir: sheet'teki job_id'ler
// oyle yazildi. Boylece normalizeTitle degisimi mevcut ilanlari "yeni" gostermez.
const legacyCityless = `${normalizeCompanyLegacy(item.company)}__${normalizeTitleLegacy(item.title)}`;
const legacySadeCity = `${normalizeCompanyLegacy(item.company)}__${normalizeTitleLegacy(item.title)}__${normalizeCity(sadeCity(item.city))}`;
const legacyRawCity  = `${normalizeCompanyLegacy(item.company)}__${normalizeTitleLegacy(item.title)}__${normalizeCity(item.city)}`;
// legacy4 = BIR ONCEKI canli formul (bosluklu sirket + yeni baslik). Sheet'teki
// job_id'lerin cogu bununla yazildi; olmazsa 2900 satirin tamami "yeni" gorunurdu.
const legacyCompanySpaced = `${normalizeCompanyLegacy(item.company)}__${normalizeTitle(item.title)}`;
// legacy5 = v3 ONCESI canli formul (city'siz ama baslikta sehir DURUYOR).
// Sheet'teki job_id'lerin cogu bununla yazildi -> dup dalgasini bu engelliyor.
const v3String = `${normalizeCompany(item.company)}__${normalizeTitleV3(item.title, item.city, item.company)}`;
// legacy6 = v4 ONCESI canli formul (sirket TAM adiyla). Sheet'teki job_id'lerin tamami
// bununla yazildi -> Filter New Ads buna da bakmali, yoksa 5.000 satir "yeni" gorunur.
const v4String = `${normalizeCompanyV4(item.company)}__${normalizeTitleV3(item.title, item.city, item.company)}`;
return {
  ...item,
  search_kw,
  dedup_key: hash(v4String),
  dedup_key_legacy6: hash(v3String),
  dedup_key_legacy: hash(legacySadeCity),
  dedup_key_legacy2: hash(legacyRawCity),
  dedup_key_legacy3: hash(legacyCityless),
  dedup_key_legacy4: hash(legacyCompanySpaced),
  dedup_key_legacy5: hash(citylessString),
  _norm_debug: v4String
};

// Job_Posts tab'indaki mevcut satirlardan yeni ilanlari ayiklar
const deRows  = $('Read Job Posts').all();

const existingKeys = new Set(
  [...deRows].map(i => i.json.job_id).filter(Boolean)
);

const incomingItems = $('Keep Best City').all();
// Hem yeni hem eski anahtara bak: sheet'teki eski satirlar eski formulle yazildi.
const newItems = incomingItems.filter(item =>
  !existingKeys.has(item.json.dedup_key) &&
  !existingKeys.has(item.json.dedup_key_legacy) &&
  !existingKeys.has(item.json.dedup_key_legacy2) &&
  !existingKeys.has(item.json.dedup_key_legacy3) &&
  !existingKeys.has(item.json.dedup_key_legacy4) &&
  !existingKeys.has(item.json.dedup_key_legacy5) &&
  !existingKeys.has(item.json.dedup_key_legacy6)
);

console.log(`Mevcut: ${existingKeys.size} · Gelen: ${incomingItems.length} · Yeni: ${newItems.length}`);
return newItems;

// EDIT ME: paste your own Google Sheet ID here (the long id in its URL) so the summary email links to YOUR sheet.
const SHEET_ID = 'YOUR_GOOGLE_SHEET_ID';

const items = $input.all();
const all = items.map(i => i.json);
const today = new Date().toLocaleDateString('de-DE');

const esc = (s) => String(s || '').replace(/[&<>"']/g, c => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
}[c]));

const cleanLoc = (v) => {
  const s = String(v == null ? '' : v).trim();
  if (!s.startsWith('{')) return s;
  try { const o = JSON.parse(s); return o.locality || o.raw || s; } catch (e) { return s; }
};
// Score Location & Language'daki BANDS ile AYNI olmali, yoksa mail ile sheet celisir.
const GREEN = 80, AMBER = 68;
const scoreColor = (s) => (s >= GREEN ? '#1a7f3a' : (s >= AMBER ? '#b8860b' : '#999'));
const scoreBg    = (s) => (s >= GREEN ? '#e6f4ea' : (s >= AMBER ? '#fef7e0' : '#f5f5f5'));

const TABLE_LIMIT = 15; // pazar basina tabloda gosterilecek ilan

function sectionHtml(label, flag, jobs) {
  const count = jobs.length;
  let html = `<h2 style="margin:28px 0 4px 0;font-size:20px">${flag} ${label} · ${count} yeni ilan</h2>`;

  if (!count) {
    return html + `<p style="color:#888;margin:4px 0 16px 0">Bu koşuda yeni ilan yok.</p>`;
  }

  const above70 = jobs.filter(j => (j.ai_score || 0) >= GREEN).length;
  const mid     = jobs.filter(j => (j.ai_score || 0) >= AMBER && (j.ai_score || 0) < GREEN).length;
  const below50 = count - above70 - mid;

  const bySource = {};
  jobs.forEach(j => { bySource[j.source] = (bySource[j.source] || 0) + 1; });
  const sourceList = Object.entries(bySource).sort((a, b) => b[1] - a[1])
    .map(([s, n]) => `<b>${esc(s)}</b>: ${n}`).join(' &middot; ');

  html += `
  <div style="display:flex;gap:8px;margin:8px 0 12px 0;flex-wrap:wrap">
    <span style="background:#e6f4ea;color:#1a7f3a;padding:4px 10px;border-radius:4px;font-weight:600">🟢 ${above70}</span>
    <span style="background:#fef7e0;color:#b8860b;padding:4px 10px;border-radius:4px;font-weight:600">🟡 ${mid}</span>
    <span style="background:#f5f5f5;color:#999;padding:4px 10px;border-radius:4px;font-weight:600">⚪ ${below50}</span>
  </div>
  <div style="background:#f4f4f4;padding:8px 12px;border-radius:6px;margin-bottom:12px;font-size:13px"><b>Kaynak:</b> ${sourceList}</div>`;

  const sorted = [...jobs].sort((a, b) => (b.ai_score || 0) - (a.ai_score || 0));
  const shown = sorted.slice(0, TABLE_LIMIT);

  html += `
  <table cellpadding="8" cellspacing="0" style="border-collapse:collapse;width:100%;font-size:13px">
    <thead>
      <tr style="background:#f8f8f8;text-align:left;border-bottom:2px solid #ddd">
        <th>Score</th><th>Source</th><th>Title</th><th>Company</th><th>Location</th><th>Notes</th><th></th>
      </tr>
    </thead>
    <tbody>`;

  shown.forEach((j, i) => {
    const score = j.ai_score || 0;
    const titleTrunc = j.title && j.title.length > 50 ? j.title.slice(0, 47) + '...' : j.title;
    const summary = j._ai_fit_summary || (j.ai_notes || '').split('\n')[0].replace(/^Fit:\s*/, '') || '-';
    const notesTrunc = summary.length > 100 ? summary.slice(0, 97) + '...' : summary;
    const bg = i % 2 === 0 ? '#fff' : '#fafafa';
    html += `
    <tr style="background:${bg};border-bottom:1px solid #eee">
      <td style="background:${scoreBg(score)};color:${scoreColor(score)};font-weight:700;text-align:center">${score}</td>
      <td style="color:#777">${esc(j.source)}</td>
      <td><b>${esc(titleTrunc)}</b></td>
      <td>${esc(j.company)}</td>
      <td>${esc(cleanLoc(j.location || j.location_raw || j.city))}</td>
      <td style="color:#666;font-size:12px;font-style:italic">${esc(notesTrunc)}</td>
      <td><a href="${esc(j.url)}" style="color:#0066cc;text-decoration:none">Aç ›</a></td>
    </tr>`;
  });

  html += `</tbody></table>`;
  if (count > TABLE_LIMIT) {
    html += `<p style="margin-top:8px;color:#777;font-size:13px"><i>+ ${count - TABLE_LIMIT} ilan daha sheet'te ↓</i></p>`;
  }
  return html;
}

const deJobs  = all.filter(j => (j.market || 'de') !== 'ist');

const g = all.filter(j => (j.ai_score || 0) >= GREEN).length;
const y = all.filter(j => (j.ai_score || 0) >= AMBER && (j.ai_score || 0) < GREEN).length;
const w = all.length - g - y;

// --- KAYNAK SAGLIGI SATIRI ---
// Build Run Log her kaynagi 7 gunluk medyaniyla karsilastirdi; sonucu burada gosteriyoruz
// ki saglik bilgisi ayri bir mail olmadan HER GUN okudugun ozette gorunsun.
let healthHtml = '';
let healthBad = false;
try {
  const rl = $('Build Run Log').first().json;
  healthBad = rl.health_alert === true;
  if (rl.health) {
    healthHtml = `<div style="margin:0 0 14px 0;padding:10px 12px;border-radius:6px;font-size:12.5px;` +
      `font-family:ui-monospace,Menlo,Consolas,monospace;` +
      (healthBad ? `background:#fdecea;color:#a61b1b;border:1px solid #f5c2c0">⚠️ KAYNAK SORUNU · `
                 : `background:#f4f6f8;color:#5b6470;border:1px solid #e3e6ea">✅ kaynaklar normal · `) +
      String(rl.health).replace(/&/g,'&amp;').replace(/</g,'&lt;') + `</div>`;
  }
} catch (e) { healthHtml = ''; }

// --- MALIYET SATIRI (2026-09-02) ---
// DIKKAT: `Format e-mail` 490s'de, `Build Run Log` 522s'de kosuyor (exec 141'de olculdu),
// yani maliyeti oradan OKUYAMAYIZ - $() firlatir. Bu yuzden kendi basina hesapliyor.
// Oranlar `* Daily Stats` node'lariyla AYNI olmali; orada degisirse burada da degistir.
const APIFY_RATES = {
  linkedin:  { node: 'LinkedIn DE Apify', row: 0.001,   start: 0.00005, runs: 4 },
  xing:      { node: 'XING Apify',        row: 0.001,   start: 0.0005,  runs: 4 },
  stepstone: { node: 'StepStone Apify',   row: 0.001,   start: 0.005,   runs: 8 },
  indeed:    { node: 'Indeed Apify',      row: 0.00005, start: 0.00001, runs: 4 },
};
let apifyUsd = 0;
const apifyBits = [];
for (const [name, cfg] of Object.entries(APIFY_RATES)) {
  let n = 0;
  // StepStone artik sadece Cuma kosuyor -> diger gunlerde $() firlatir, 0 sayilir.
  try { n = $(cfg.node).all().length; } catch (e) { n = 0; }
  if (!n) continue;
  apifyUsd += n * cfg.row + cfg.start * cfg.runs;
  apifyBits.push(`${name} ${n}`);
}
let cw = 0, cr = 0, ui = 0, ot = 0, scoredN = 0;
try {
  for (const i of $('Score Location & Language').all()) {
    const u = (i.json && i.json._usage) || {};
    cw += Number(u.cache_creation_input_tokens || 0);
    cr += Number(u.cache_read_input_tokens || 0);
    ui += Number(u.input_tokens || 0);
    ot += Number(u.output_tokens || 0);
    scoredN++;
  }
} catch (e) {}
// Haiku 4.5: in $1/MTok (1h TTL yazma x2, okuma x0.1), out $5/MTok
const claudeUsd = (cw * 2.0 + cr * 0.1 + ui * 1.0) / 1e6 + (ot * 5.0) / 1e6;
const cacheHit  = (cw + cr) > 0 ? Math.round((cr / (cw + cr)) * 100) : 0;
const totalUsd  = apifyUsd + claudeUsd;
const worthyN   = all.filter(j => (j.ai_score || 0) >= AMBER).length;
const usd = (v) => '$' + (v < 0.1 ? v.toFixed(3) : v.toFixed(2));
const costHtml = `<div style="margin:0 0 14px 0;padding:10px 12px;border-radius:6px;font-size:12.5px;` +
  `font-family:ui-monospace,Menlo,Consolas,monospace;background:#f4f6f8;color:#5b6470;` +
  `border:1px solid #e3e6ea">` +
  `\ud83d\udcb6 <b>${usd(totalUsd)}</b> bu tarama &middot; Apify ${usd(apifyUsd)}` +
  (apifyBits.length ? ` (${apifyBits.join(' &middot; ')})` : '') +
  ` &middot; Claude ${usd(claudeUsd)} (${scoredN} ilan, cache %${cacheHit})` +
  (worthyN ? ` &middot; <b>${usd(totalUsd / worthyN)}</b> / uygun ilan` : '') +
  `</div>`;

const subject = `${healthBad ? '⚠️ ' : ''}🔔 ${deJobs.length} yeni ilan · 🟢${g} 🟡${y} ⚪${w} (${today})`;

let html = `
<div style="font-family:-apple-system,BlinkMacSystemFont,sans-serif;font-size:14px;color:#222;max-width:900px">
  <h1 style="margin:0 0 4px 0;font-size:26px">Job Scan Summary</h1>
