const items = $input.all();

// acronyms matched on word boundaries so "email" / "mobile" do not false-positive
const RX = /\b(bi|ai|ml|nlp|llm|mlops|genai)\b/i;

// A title must contain at least one of these (or match RX above).
// Tune this list if the scanner is missing roles you care about.
const DATA = ['data', 'daten', 'analyst', 'analytics engineer', 'quantitativ', 'business intelligence', 'power bi',
  'sql', 'tableau', 'looker', 'report', 'bericht', 'scientist', 'insight', 'statistic',
  'kennzahl', 'dashboard', 'machine learning', 'deep learning', 'artificial intelligence',
  'künstliche intelligenz', 'computer vision', 'generative', 'mlops', 'big data',
  'data engineer', 'data science', 'dwh', 'dbt',
  // roles requested 2026-08-26: 'consultant' also covers 'IT-Consultant' and
