  'consultant', 'market intelligence', 'junior',
  // non-data titles the keyword list deliberately searches for
  'founder', 'product manager', 'produktmanager', 'produkt manager',
  // 2026-08-28: IZIN LISTESI GERI ACILDI, ama once ONU DUSUREN IKI BOSLUK kapatildi.
  // (a) 'product owner' hic yoktu - sadece 'product manager' vardi; exec 128'de TEK
