// yazilirsa). 'shk' KASITLI YOK - Sanitaer-Heizung-Klima kisaltmasi ve cok kisa.
const STUDENT_RX = /studentische|hilfskr(a|ä)ft|\bhiwi\b|student\s+assistant/i;

// SENIORITE / AKADEMIK basliklar (2026-08-27, kullanici karari "aggressive rule").
// Kaynak filtreleri zaten senior/lead/head/principal/student/trainee/werkstudent/
// praktikum/ausbildung eliyor; bunlar ONLARIN KACIRDIKLARI. Haiku'nun
// seniority_mismatch bayragi ancak PARALI cagridan SONRA ogreniliyor, o yuzden
// basliktan yakalanabilenler burada BEDAVA eleniyor.
// 3.794 gercek baslikta olculdu: 144 satir yakalaniyor, %87,5'i zaten elenecekti.
// KABUL EDILEN BEDEL: 7 apply+ satir da gidiyor (2'si strong_apply - Founding CTO,
// Director Fleet Intelligence). Kullanici bunu bilerek onayladi.
// 'promotion' KASITLI DISARIDA: "Promotion Analyst (m/w/d)" pazarlama promosyonu,
// doktora degil - yanlis pozitif olarak olculdu.
// KELIME SINIRI: 'architect' compound'larda da gecerli (Data Architect), ama
// \bstaff\b / \bvp\b / \bchief\b sinirsiz birakilirsa 'Stafford', 'vpn' gibi
// kelimeleri de yakalar.
const SENIOR_RX = /architect|architekt|\bstaff\b|\bleiter\b|\bleiterin\b|\bleitung\b|teamlead|\bdirector\b|\bdirektor\b|\bchief\b|\bvp\b|\bcto\b|\bceo\b|professor|\bphd\b|doktorand/i;

// 'engineering manager' EKLENDI 2026-09-01 (kullanici karari). Kendi basina
// "Engineering Manager" zaten DUSUYORDU - ama izin listesinde veri terimi olmadigi icin,
// kasitli bir kural oldugu icin DEGIL. "Engineering Manager, Data & Analytics" (Staffbase,
// 08-17, 77 puan) 'data' + 'analytics' sayesinde izin listesini geciyor ve SENIOR_RX'te
// 'manager' bulunmadigi icin sagkaliyordu. Substring eslesmesi "Data Engineering Manager"
// gibi varyantlari da yakalar; "Senior Engineering Manager" zaten SENIOR_RX'e takiliyor.
const BLOCK = ['datenschutz', 'dateneingabe', 'datenerfassung', 'data entry', 'engineering manager'];

// SAF YAZILIM MUHENDISLIGI (2026-08-28, kullanici karari). Sadece BITISIK yazilmis
// "software engineer" kaliplarini eler - tek basina "engineer" ELENMEZ, cunku
// "Data Engineer" / "Analytics Engineer" tam da aradigimiz roller.
// Yakalar: "Software Engineer", "Software-Engineer", "Softwareengineer", "Software Engineering".
// DIKKAT: "Software Engineer Analytics" gibi GERCEK data rollerini de eler -
// artifact'taki acik maddede bu baslik ISTENEN roller arasindaydi. Istenirse
// muafiyet tek satir: `&& !/analytic|data|\bbi\b/i.test(title)`.
const SOFTWARE_ENG_RX = /\bsoftware[\s\-]*engineer/i;


// ---- ALMANYA DISI SEHIRLER (2026-09-01, kullanici listesi) ----
// Bu ilanlar Claude'a HIC gonderilmiyor - eleme UCRETSIZ ve scoring'den ONCE.
// TAM ESLESME sart, substring DEGIL: "Linz" listede ama Almanya'da "Linz am Rhein"
// var; "Bern" listede ama "Bernau" Almanya'da. Normalize edilmis sehir adi birebir
// esitse duser. Iki taraf da ayni normalize'dan geciyor (kucuk harf, aksan atilir).
const BLOCKED_CITY_LIST = [
  // Avusturya
  'Wien','Graz','Linz','Salzburg','Wels','Leonding','Spittal an der Drau','Bruck an der Mur',
  'Premstätten bei Vasoldsberg','Kalsdorf bei Graz','Großhöflein','Trumau','Elsbethen',
  'Waidhofen an der Ybbs','Krems an der Donau','Hörsching','Hard',
  // Isvicre
  'Zürich','Bern','Basel','Genf','Luzern','Zug','Lausanne','Aarau','Emmen','Oensingen','Sarnen',
  'Ebikon','St. Gallen','Muri-Gümligen','Lenzburg','Winterthur','Volketswil','Wallisellen',
  'Dübendorf','Mägenwil','Affoltern am Albis','Ruswil','Härkingen','Zuchwil','Visp','Schmerikon','Herisau',
  // diger
  'Thessaloniki','Malaga','Lissabon','Košice',
];
const normCity = s => String(s || '').toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
const BLOCKED_CITIES = new Set(BLOCKED_CITY_LIST.map(normCity));

// 2026-09-01 AKSAMI DUZELTILDI: ilk surum SADECE tam normalize edilmis sehir adini
// karsilastiriyordu, ve exec 141'de Arbeitsagentur'dan gelen city="Wien,Landstrasse"
// ELENMEDI - Claude'a gitti ve 82 puan aldi. Kaynaklar sehre ILCE/SEMT ekleyebiliyor.
// Cozum: hem TAM adi hem de ilk ayirici oncesindeki parcayi dene. Sadece ILK parca -
// tum parcalari denemek "Berlin, Wien" gibi cok sehirli bir alanda gercek bir Alman
// ilanini oldururdu. Ayirici olarak virgul, slash ve acilis parantezi kullaniliyor.
const cityKeys = (v) => {
  const whole = normCity(v);
  const firstPart = normCity(String(v || '').split(/[,\/(]/)[0]);
  return [whole, firstPart].filter(Boolean);
};
const isBlockedCity = (v) => cityKeys(v).some(k => BLOCKED_CITIES.has(k));

// StepStone bazi ilanlari COK SEHIRLI donduruyor:
//   "Aachen, Berlin, Frankfurt am Main, ..., Košice, ..., München"
// Boyle bir ilan GERCEK bir Alman ilani; sadece location_raw'da yabanci bir sehir
// de geciyor. Bu yuzden karar HER ZAMAN cozulmus `city` alanina gore verilir,
// location_raw'daki tekil kelimeye gore ASLA.
// `city` bloklanmissa ama location_raw'da bir Alman merkezi varsa ilan DUSMEZ,
// city o merkeze cevrilir (ornek: city=Graz, loc="Graz, Wien, Berlin, Dortmund").
// Alman merkezi yoksa ve city bloklu ise ilan duser.
const DE_HUBS = new Set(['berlin','munchen','munich','hamburg','frankfurt','frankfurt am main',
  'koln','cologne','stuttgart','dusseldorf','leipzig','hannover','nurnberg','bremen','dortmund',
  'essen','dresden','mannheim','karlsruhe','bonn','munster','augsburg','wiesbaden','bielefeld']);
let foreignDropped = 0, cityRewritten = 0;

const kept = items.filter(it => {

  // --- yurt disi sehir elemesi (baslik testlerinden ONCE, en ucuzu once) ---
  if (isBlockedCity(it.json.city)) {
    const hub = String(it.json.location_raw || '')
      .split(/[,;\/|]/).map(s => s.trim()).filter(Boolean)
      .find(tok => DE_HUBS.has(normCity(tok)));
    if (hub) { it.json.city = hub; cityRewritten++; }
    else { foreignDropped++; return false; }
  }

  // strip soft hyphens: some sources sprinkle U+00AD into titles ("Da­ta Ana­lyst")
  const title = String(it.json.title || '').replace(/­/g, '').toLowerCase();

  // IZIN LISTESI (2026-08-28 aksami kaldirildi, ayni gun GERI ACILDI - kullanici karari).
  // Baslik en az bir veri/analiz terimi (veya RX kisaltmasi) ICERMEK ZORUNDA.
  // Kaldirildigi kisa surede exec 128 uzerinde olculdu: liste kapaliyken 462 ilan
  // geciyordu, acikken 286 - yani ~176 ilan/tarama ve ~$0.48/tarama Haiku farki.
  // Geri acilirken 'product owner' ve 'analytics' EKLENDI (yukaridaki nota bak),
  // yoksa listeyi aynen geri koymak kullanicinin acikca korumak istedigi
  // Product Owner rollerini tekrar oldururdu.
  const dataHit = DATA.some(w => title.includes(w)) || RX.test(title);
  if (!dataHit) return false;
  if (BLOCK.some(w => title.includes(w))) return false;
  if (SOFTWARE_ENG_RX.test(title)) return false;
  if (INTERN_RX.test(title)) return false;
  if (STUDENT_RX.test(title)) return false;
  if (SENIOR_RX.test(title)) return false;
  return true;
});

const seniorDropped = items.filter(it => SENIOR_RX.test(String(it.json.title || '').replace(/\u00AD/g, '').toLowerCase())).length;
console.log(`Relevance filter: ${items.length} -> ${kept.length} (dropped: ${items.length - kept.length}, of which seniority/academic: ${seniorDropped}, yurt disi sehir: ${foreignDropped}; city duzeltildi: ${cityRewritten})`);
return kept;

// Build Run Log — bu koşunun sağlık özeti; tek satır üretir (runs tabına yazılır).
//
// Sayımlar DEDUP'TAN ÖNCEKİ ham çıktıdan alınır: "kaynak bozuk mu?" sorusunun cevabı
// entegrasyonun veri döndürüp döndürmediğidir. Dedup sonrası bakarsak, 50 ilan döndürüp
// hepsi mükerrer çıkan sağlıklı bir kaynak "sıfır" görünür ve yanlış alarm verir.
//
// Kaynak = 6 ENTEGRASYON (platform değil). 2026-08-26: agentx emekli oldu, yerine
// curious_coder LinkedIn geldi (sütun adı geçmiş için 'agentx_de' KALDI) ve
// kaix/indeed-scraper 6. kaynak olarak eklendi -> 'indeed' sütunu.

const SRC = {
  adzuna: 'Adzuna Fields',
  arbeitsagentur: 'Arbeitsagentur Fields',
  agentx_de: 'LinkedIn DE Fields',
  xing: 'XING Fields',
  stepstone: 'StepStone Fields',
  indeed: 'Indeed Fields',
};

const row = {
  run_at: new Date().toISOString(),
  execution_id: String($execution.id || ''),
};

// StepStone haftada bir, sadece Cuma (2026-09-01). Hem zero_sources hem de asagidaki
// medyan karsilastirmasi bunu bilmek zorunda - tek yerden hesapla.
const isStepStoneDay = new Intl.DateTimeFormat('en-US', { timeZone: 'Europe/Berlin', weekday: 'short' })
  .format(new Date()) === 'Fri';

let raw = 0;
const zero = [];

for (const col of Object.keys(SRC)) {
  let n = 0;
  try {
    // Kaynak hata verip hiç çalışmadıysa $() fırlatır -> 0 = gerçekten sıfır dönmüş demektir.
    n = $(SRC[col]).all().length;
  } catch (e) {
    n = 0;
  }
  row[col] = n;
  raw += n;
  // StepStone artik SADECE CUMA kosuyor (2026-09-01). Diger gunlerde 0 dondurmesi
  // NORMAL - 'zero_sources'a yazilirsa her gun yanlis alarm uretir.
  if (n === 0 && !(col === 'stepstone' && !isStepStoneDay)) zero.push(col);
}

// DIKKAT: $input artik 'Read Run History' (runs tabi). Ilanlari adiyla aliyoruz.
const yeni = $('Score Location & Language').all();
const mkt = (i) => String((i.json && i.json.market) || '').trim().toLowerCase();

// --- API kullanimi: prompt cache gercekten calisiyor mu? ---
// cache_read >> 0 ve cache_write ~ tek seferlik ise saglikli.
let cw = 0, cr = 0, ui = 0, ot = 0;
for (const i of yeni) {
  const u = (i.json && i.json._usage) || {};
  cw += Number(u.cache_creation_input_tokens || 0);
  cr += Number(u.cache_read_input_tokens || 0);
  ui += Number(u.input_tokens || 0);
  ot += Number(u.output_tokens || 0);
}
row.cache_write_tokens = cw;
row.cache_read_tokens  = cr;
row.uncached_in_tokens = ui;
row.output_tokens      = ot;
row.cache_hit_pct = (cw + cr) > 0 ? Math.round((cr / (cw + cr)) * 100) : 0;
// Haiku 4.5: in $1/MTok (write x1.25 @1h TTL: x2, read x0.1), out $5/MTok
row.est_cost_usd = Number(
  ((cw * 2.0 + cr * 0.1 + ui * 1.0) / 1e6 + (ot * 5.0) / 1e6).toFixed(4)
);

// --- ANAHTAR KELIME VERIMI ---
// Her ilan hangi aramadan geldigini 'search_kw' ile tasiyor. Uc sayi, bir terimin
// parasini hak edip etmedigini gosterir:
//   found  = bu terimin TEK BASINA getirdigi ilan (baska terim zaten bulmamis)
//   scored = bunlardan kacinin bedava kapilari gecip Claude'a gonderildigi -> PARA BURADA
//   apply  = bunlardan kacinin 60+ puan aldigi, yani gercekten basvurulabilir oldugu
// Bir hafta sonra 'apply' surekli 0 olan terimleri Keywords DE'den cikar.
const kwStats = {};
const bump = (k, field) => {
  const key = String(k || '(kaynak bilinmiyor)');
  if (!kwStats[key]) kwStats[key] = { found: 0, scored: 0, apply: 0 };
  kwStats[key][field]++;
};
try {
  for (const i of $('Keep Best City').all()) bump(i.json.search_kw, 'found');
} catch (e) {}
try {
  for (const i of $('German Gate').all()) bump(i.json.search_kw, 'scored');   // 2026-08-27: Trim -> German Gate (Trim artik Claude'a gideni gostermiyor)
} catch (e) {}
for (const i of yeni) {
  if ((i.json.total_score || 0) >= 60) bump(i.json.search_kw, 'apply');
}
// Her terim kendi satirinda — e-Tabloda hucre icinde okunabilir kalsin.
row.kw_yield = Object.entries(kwStats)
  .sort((a, b) => b[1].apply - a[1].apply || b[1].found - a[1].found)
  .map(([k, v]) => `${k}: ${v.found} found / ${v.scored} scored / ${v.apply} apply`)
  .join('\n');
console.log('Anahtar kelime verimi:\n' + row.kw_yield);

row.raw_jobs = raw;                    // dedup öncesi toplam
row.new_jobs = yeni.length;            // skorlanıp yazılan yeni ilan
row.de_jobs = yeni.filter((i) => mkt(i) === 'de').length;
row.zero_sources = zero.join(', ');

// --- KAYNAK SAGLIGI: her kaynak KENDI 7 gunluk medyaniyla karsilastirilir ---
// Sadece "sifir mi?" diye sormak yetmiyordu: 21.08'de Agentx 342 yerine 36 ilan dondu,
// zero_sources bos kaldi ve kosu saglikli gorundu. Retry'lar kapatildigi icin tek bir
// basarisiz anahtar cagrisi artik kalici kayip demek — buyuklugu de olcmek gerekiyor.
let history = [];
try { history = $('Read Run History').all().map(i => i.json || {}); } catch (e) { history = []; }
const lastRuns = history.slice(-7);          // bugun henuz yazilmadi, hepsi gecmis
const median = (arr) => {
  const s = arr.map(Number).filter(n => Number.isFinite(n) && n > 0).sort((a, b) => a - b);
  if (!s.length) return null;
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
};
const DEGRADED_RATIO = 0.30;                 // medyanin %30'unun altina duserse alarm
const parts = [];
let alert = false;
for (const col of Object.keys(SRC)) {
  const med = median(lastRuns.map(r => r[col]));
  const n = row[col];
  let state = 'ok';
  // StepStone SADECE CUMA kosuyor (2026-09-01). Diger gunlerde 0 dondurmesi normal:
  // ne DOWN ne DEGRADED sayilmali, yoksa haftada 4 gun yanlis alarm ve mail konusunda
  // "⚠️" cikar. Medyan da bozulur (sifirli gunler medyani asagi ceker), o yuzden
  // kosmadigi gunlerde satirda 'off' yazip karsilastirmayi tamamen atliyoruz.
  if (col === 'stepstone' && !isStepStoneDay) {
    parts.push(`${col}=off`);
    continue;
  }
  if (n === 0) { state = 'DOWN'; alert = true; }
  else if (med && n < med * DEGRADED_RATIO) { state = 'DEGRADED'; alert = true; }
  parts.push(`${col}=${n}${med ? '/med' + Math.round(med) : ''}${state === 'ok' ? '' : ' ' + state}`);
}
row.health = parts.join(' · ');
row.health_alert = alert;
console.log((alert ? 'KAYNAK ALARMI: ' : 'Kaynak sagligi: ') + row.health);

return [{ json: row }];

// EDIT ME: how many days back each source should search, and how many sources x keywords
// you're calling per run. More keywords/days = more Apify calls = more cost.
const LOOKBACK_DAYS = 1;

return ["BI Analyst", "Data Analyst", "Data Engineer", "Business Analyst", "Quant Analyst", "Analytics Engineer", "Data Scientist", "Product Manager"].map(kw => ({ json: { kw, lookback_days: LOOKBACK_DAYS } }));

// Deterministic detector for an EXPLICITLY STATED German-language requirement.
// Needed because Haiku's `explicit_c1_c2` tier over-fires: it infers C1 from "the ad
// is written in German", so 972 of 1143 tagged rows never state a level at all.
//
// German ads name the language BEFORE a CEFR level ("Deutsch mindestens C1") and
// AFTER an adjective ("verhandlungssichere Deutschkenntnisse"). So look in the
// direction the marker implies, and reject if an English word sits between the
// language word and the marker — that means the level belongs to English.
// Sheet'teki description'da satir sonlari silinmis: 'Level C1WARUM MIT UNS'.
// Bu yuzden \b KULLANILAMAZ; sagda yapisik BUYUK harf serbest, rakam degil.
const CEFR = /(?<![A-Za-z0-9])C[12](?![0-9])/g;                                             // level comes after the language
const ADJ  = /verhandlungssicher\w*|flie(?:ss|ß)end\w*|muttersprach\w*/gi; // language comes after the marker
const DE   = /deutsch(?!land)\w*|german\b/gi;   // (?!land): 'Deutschlandticket' bir dil talebi DEGIL (859 satirda geciyor, 17'si CEFR/sifat yakininda)
const EN   = /englisch\w*|english\w*/gi;
// "Deutsch ODER Englisch" bir engel DEGIL; "Deutsch UND Englisch" engeldir.
const EITHER_OR = /(deutsch\w*|german)\W{0,8}(oder|or|\/|und\s*\/\s*oder)\W{0,8}(englisch\w*|english)|(englisch\w*|english)\W{0,8}(oder|or|\/)\W{0,8}(deutsch\w*|german)/i;
const SOFT = /w(?:ü|ue)nschenswert|von\s+Vorteil|nice[- ]to[- ]have|a\s+plus|ideal(?:erweise)?|bonus|kein\w*\s+deutsch|nicht\s+erforderlich|not\s+required/i;

const lastBefore = (t, re, at) => { let r=-1,m; re.lastIndex=0;
  while ((m=re.exec(t))!==null) { if (m.index+m[0].length<=at) r=m.index+m[0].length; else break; } return r; };
const firstAfter = (t, re, at) => { let m; re.lastIndex=0;
  while ((m=re.exec(t))!==null) if (m.index>=at) return m.index; return -1; };

// SEVIYE AYRIMI (2026-08-26): ilan C1 mi C2 mi istiyor? Ceza buna gore degisiyor.
// Sifatlarda CEFR yazmaz, o yuzden esleme: muttersprachlich = ANA DIL = C2;
// verhandlungssicher / fliessend = C1. Ilanda birden fazla isaret varsa EN KATISI kazanir.
const ADJ_C2 = /muttersprach\w*/i;

// Dondurur: 'C2' | 'C1' | null. null = ilan acikca bir seviye ISTEMIYOR.
const germanLevel = (text) => {
  const t = String(text || '');
  const soft = (at, len) => SOFT.test(t.slice(Math.max(0, at-45), at+len+45));

  let level = null;
  // C2 en kati: bir kez gorulduyse artik dusmez.
  const bump = (lv) => { if (lv === 'C2') level = 'C2'; else if (level === null) level = 'C1'; };

  let m;
  CEFR.lastIndex = 0;
  while ((m = CEFR.exec(t)) !== null) {
    const at = m.index;
    const de = lastBefore(t, DE, at);
    if (de < 0 || at - de > 75) continue;          // no German word leading into this level
    if (t.slice(de, at).match(EN)) continue;       // ...but an English word got in between
    if (soft(at, m[0].length)) continue;
    if (EITHER_OR.test(t.slice(Math.max(0, at-60), at+60))) continue;
    bump(m[0].toUpperCase());                      // ARTIK ERKEN CIKMIYOR: en katiyi bulmak icin taramaya devam
  }
  ADJ.lastIndex = 0;
  while ((m = ADJ.exec(t)) !== null) {
    const at = m.index, end = at + m[0].length;
    const de = firstAfter(t, DE, end);
    if (de < 0 || de - end > 40) continue;
    if (t.slice(end, de).match(EN)) continue;
    if (soft(at, m[0].length)) continue;
    if (EITHER_OR.test(t.slice(end, end + 70))) continue;
    bump(ADJ_C2.test(m[0]) ? 'C2' : 'C1');
  }
  return level;
};

// Kapi ayni kaldi: seviye farketmeksizin acik bir Almanca talebi 'skip' demek.
