// ======================================================================
const LOCATION_POINTS = { berlin: 100, munich: 85, hamburg: 70 };
const REMOTE_POINTS        = 100;   // fully remote is as good as home
const HYBRID_ELSEWHERE      = 55;   // hybrid in another German city
const ONSITE_ELSEWHERE      = 45;   // on-site in another German city
const UNKNOWN_CITY_POINTS   = 45;   // ad did not say -> treat as "other Germany"

// DENEYIM: ilanin istedigi yil ile adayin yili arasindaki FARK puanlanir.
// Adaydan az/esit isteyen ilan tam puan; her fazla yil ceza. Ilan yil soylemiyorsa
// (vakalarin cogu) ne odullendir ne cezalandir -> notr-ustu bir deger.
// EDIT ME: must match CFG.experience_years in "Prepare AI Scoring Prompt" -- the two are not linked automatically.
const CANDIDATE_YEARS     = 3;    // CFG.experience_years ile ayni
const EXPERIENCE_PENALTY  = 30;   // adayin ustundeki HER FAZLA YIL icin duz ceza (21.08: 25 -> 30)
const EXPERIENCE_UNSTATED = 100;  // ilan yil belirtmemis -> ceza YOK (Alman ilanlarinin cogu
                                  // sayi yazmiyor; bu bilesen sadece ACIKCA cok yil isteyeni eler)

// Duz dogru: 3 yil ve altini isteyen ilan 100, her fazla yil -30, TABAN YOK.
// Negatif bilesen kasitli: 8+ yil isteyen ilan sadece kredi almamakla kalmaz,
// toplam puandan duser. Toplam da negatif olabilir (21.08'de onaylandi).
const experienceScore = (req) => {
  const r = Number(req);
  if (!Number.isFinite(r) || r <= 0) return EXPERIENCE_UNSTATED;
  const gap = Math.ceil(r) - CANDIDATE_YEARS;
  if (gap <= 0) return 100;
  return 100 - gap * EXPERIENCE_PENALTY;   // TABAN YOK: 7y -> -20, 8y -> -50, 10y -> -110
};

// BANT ESIKLERI — 2026-08-21'de yeni olcege tasindi.
// Deneyim bileseni ilanlarin buyuk cogunlugunda 100 (yil belirtilmemis) oldugu icin
// %25'lik agirlik SABIT davraniyor: tum puanlar ~10 puan yukari kaydi ve standart
// sapma 13.4'ten 10.5'e dustu. Eski esikler birakilsaydi "strong_apply" 3.023 satirlik
// arsivde 157'den 463'e cikardi — kisa liste olmaktan cikardi. Asagidaki degerler o
// gercek dagilimda eski bant BUYUKLUKLERINI yeniden uretiyor (quantile eslesmesi).
const BANDS = { strong: 80, apply: 68, maybe: 57 };

// de_level -> puan. native/fluent/very_good hepsi 1: "sehr gute Deutschkenntnisse"
// bir B2 aday icin verhandlungssicher kadar kapali bir kapi sayiliyor (grup A, 500 satir,
// davranis DEGISMIYOR). Asagisi kademeli: good 30, basic 60.
// ============================ DIL PUANI (yeniden tasarim, 2026-08-27 gec aksam) ==========
// EDIT ME: replace with YOUR German/English proficiency (native/fluent/very_good/good/basic/none).
// ADAY PROFILI: Almanca B2, Ingilizce C2. Bu iki capa her seyi belirliyor:
//   * Ingilizce C2 oldugu icin HICBIR Ingilizce talebi engel DEGIL. Ingilizce talebi sadece
//     is yerinin hangi dilde calistigini soyleyen bir SINYAL.
//   * Almanca B2 oldugu icin kesim noktasi `good` (B1-B2, aday geciyor) ile
//     `very_good` (B2-C1, tam sinirda) ARASINDA.
// ADIM 1 - Almanca seviyesi TAVANI koyuyor: kapi B2 bir aday icin ne kadar acik?
const DE_BASE = {
  none:      100,   // talep yok
  basic:     100,   // A1-A2, cok altinda
  good:      100,   // B1-B2, aday geciyor
  mentioned: 100,   // Almanca aniliyor ama SEVIYE YOK -> beyan edilmis bir engel degil
  very_good:  60,   // B2-C1, tam sinirda (kullanici 50 -> 60, 2026-08-27)
  fluent:     20,   // C1, adayin ustunde
  native:      0,   // C2 / ana dil -> kapali
};
// ADIM 2 - Ingilizce KIYASI tavanin ne kadarini koruyacagini belirliyor.
const LEVEL_RANK = { none: 0, mentioned: 0.5, basic: 1, good: 2, very_good: 3, fluent: 4, native: 5 };
const GERMAN_AD_FACTOR = 0.5;   // Almanca ilanda simetrik talep -> yarisi
// EN > DE  -> x1.0  (Ingilizce daha guclu isteniyor: calisma dili Ingilizce, IYI sinyal)
// EN = DE  -> ilan Almanca ise x0.5, degilse x1.0
// EN < DE  -> x0.5  (Almanca baskin) - kullanici bu durumu belirtmedi, muhafazakar secim


const LANGUAGE_POINTS = {
  en_only:        100,
  en_over_de:      75,
  de_over_en:      45,
  explicit_c1_c2:   1,   // B2 aday icin kapali kapi: neredeyse tamamen sifirla
};

// NOT (2026-08-27): ACIK C1/C2 CEZASI (-50 / -100) SILINDI - OLU KODDU.
// `German Gate` node'u artik bu ilanlari PARALI cagridan ONCE eliyor, yani buraya
// german_blocked === true ile hicbir satir ULASMIYOR; ceza dali asla calismiyordu.
// Kapi burada DURUYOR (asagidaki recommendation merdiveninde) savunma katmani olarak.
// Tier'in kendi tablo degeri (explicit_c1_c2 -> 1) degismedi.

// city spellings vary by source: München / Muenchen / Munich
const normCity = (s) => String(s || '')
  .toLowerCase()
  .replace(/ü/g, 'u').replace(/ö/g, 'o').replace(/ä/g, 'a').replace(/ß/g, 'ss')
  .replace(/muenchen|munchen/g, 'munich')
  .replace(/[^a-z ]/g, ' ')
  .trim();

const locationScore = (city, mode) => {
  if (mode === 'remote') return REMOTE_POINTS;
  const c = normCity(city);
  for (const [name, pts] of Object.entries(LOCATION_POINTS)) {
    if (c.includes(name)) return pts;
  }
  if (!c) return UNKNOWN_CITY_POINTS;
  return mode === 'hybrid' ? HYBRID_ELSEWHERE : ONSITE_ELSEWHERE;
};

const out = items.map(it => {
  const j = it.json;

  // ACIKCA C1/C2 Almanca isteyen ilan B2 aday icin KAPALI KAPI. Ilanin KENDI metnine bakar.
  // Once hesaplaniyor cunku artik dil bilesenini de belirliyor (seviyeye gore -50 / -100).
  const german_level   = germanLevel(j._desc_orig || j.description || '');
  const german_blocked = german_level !== null;

  const location_score   = locationScore(j.ai_city || j.city, j.work_mode);
  // 2026-08-27: dil puani artik Haiku'nun BIRLESIK tier'inden degil, AYRI CIKARILAN
  // `de_level`dan geliyor. Ilanin KENDI dili SADECE de_level === 'none' iken tie-break.
  // Boylece "Sehr gute Englischkenntnisse (C1)" gibi ilanlar bir daha Almanca talebi
  // sayilmiyor (arsivde 68 satir bu yuzden 1 puan almisti, 30'u Almanca'yi HIC anmiyordu).
  const de_level = j.de_level;
  const en_level = j.en_level;
  const ad_lang  = j.ad_language === 'en' ? 'en' : 'de';
  const de_rank  = LEVEL_RANK[de_level], en_rank = LEVEL_RANK[en_level];
  const cmp = de_rank === undefined || en_rank === undefined ? null
            : en_rank > de_rank ? 'en_higher'
            : en_rank === de_rank ? 'equal' : 'de_higher';
  const language_score = DE_BASE[de_level] === undefined
    ? (LANGUAGE_POINTS[j.language_tier] ?? LANGUAGE_POINTS.de_over_en)     // eski satir / geri uyum
    : Math.round(DE_BASE[de_level] * (
          cmp === 'en_higher' ? 1
        : cmp === 'equal'     ? (ad_lang === 'de' ? GERMAN_AD_FACTOR : 1)
        :                       GERMAN_AD_FACTOR));
  const experience_score = experienceScore(j.required_years);
  const match_score      = Number(j.cv_match_score) || 0;

  const total = Math.round(
    match_score      * WEIGHTS.match +
    experience_score * WEIGHTS.experience +
    language_score   * WEIGHTS.language +
    location_score   * WEIGHTS.location
  );

  const recommendation =
    j.parse_error          ? 'error'  :
    j.seniority_mismatch   ? 'skip'   :
    german_blocked         ? 'skip'   :
    total >= BANDS.strong  ? 'strong_apply' :
    total >= BANDS.apply   ? 'apply'  :
    total >= BANDS.maybe   ? 'maybe'  : 'skip';

  const CV_LABEL = {
    data_analyst:     'Data Analyst / BI',
    data_eng_science: 'Data Scientist / Analytics Eng / Data Eng',
    business_analyst: 'Business Analyst',
    quant_analyst:    'Quant Analyst',
  };

  const notes = [
    j.chosen_cv ? `CV: ${CV_LABEL[j.chosen_cv] || j.chosen_cv}  (match ${match_score})` : null,
    j.assessment    ? j.assessment : null,
    j.company_brief ? `Company: ${j.company_brief}` : null,
    `Mode: ${j.work_mode} · Lang: de=${j.de_level ?? j.language_tier ?? '?'}/en=${j.en_level ?? '?'} ad=${j.ad_language ?? '?'}${cmp ? ' [' + cmp + ']' : ''} -> ${language_score}${german_blocked ? ` (${german_level} ACIK -> skip)` : ''} · Exp: ` +
      (j.required_years ? `${j.required_years}y istiyor (${experience_score})` : `belirtilmemis (${experience_score})`),
    j.new_cv_needed      ? '⚡ No good CV variant — consider writing one' : null,
    j.seniority_mismatch ? '⚡ Seniority / student-level mismatch' : null,
  ].filter(Boolean).join('\n');

  return { json: {
    ...j,
    location_score,
    language_score,
    experience_score,
    total_score: total,
    ai_score: total,     // alias: Format e-mail + existing sheet column
    ai_notes: notes,     // alias: same
    recommendation,
    notes,
  }};
});

const noYears = out.filter(o => !o.json.required_years).length;
console.log(`Deneyim: ${out.length - noYears} ilan yil belirtti, ${noYears} belirtmedi (${EXPERIENCE_UNSTATED} puan = cezasiz)`);

const n = out.length || 1;
const avg = Math.round(out.reduce((a, o) => a + o.json.total_score, 0) / n);
const strong = out.filter(o => o.json.total_score >= 75).length;
console.log(`Scored ${out.length} ads · avg ${avg} · >=75: ${strong}`);
