}

// --- Dedup node'undaki normalizasyonun birebir kopyasi ---
function trSafe(s) {
  return String(s || '')
    .replace(/İ/g, 'i')
    .toLowerCase()
    .replace(/\u0307/g, '')
    .replace(/ı/g, 'i')
    .replace(/ş/g, 's')
    .replace(/ğ/g, 'g')
    .replace(/ç/g, 'c');
}
function normalizeCompany(s) {
  if (!s) return '';
  // Dedup node'uyla AYNI v2 formulu: sondaki .replace(/\s+/g,'') bosluk farkini siler.
  return trSafe(s)
    .replace(/\b(gmbh|ag|se|kg|co\.?|ltd|inc|llc|& co\.? kg|mbh|deutschland|holding|group|consulting)\b/g, '')
    .replace(/\b(a\.?s\.?|ltd\.?\s*sti\.?|sti\.?|anonim sirketi|limited sirketi)\b/g, '')
    .replace(/[^\w\s]/g, ' ').replace(/\s+/g, ' ').trim()
    .replace(/\s+/g, '');
}
function normalizeTitle(s) {
  if (!s) return '';
  return trSafe(s)
    .replace(/[\u00ad\u200b\u200c\u200d\ufeff]/g, '')
    .replace(/^(zwei|drei|vier|mehrere|two|three|several)\s+/, '')
    .replace(/\((m\/w\/d|f\/m\/d|w\/m\/d|m\/f\/d|d\/f\/m|m\/f\/x|w\/m\/x|all genders|gn|m\/w|d)\)/g, '')
    .replace(/\b(junior|jr\.?|entry level|associate)\b/g, '')
    .replace(/[^\w\s]/g, ' ').replace(/\s+/g, ' ').trim();
}
const key = (company, title) => `${normalizeCompany(company)}__${normalizeTitle(title)}`;
// Indeed'in ?jk= parametresi ilanin KIMLIGIDIR. Sorgu dizesi kesilirse TUM Indeed
// ilanlari ayni URL'e (https://de.indeed.com/viewjob) collapse oluyor ve Applied
// listesindeki TEK bir Indeed satiri butun kaynagi eliyordu (2026-08-26'da olcum:
// 9 Indeed ilaninin 9'u da burada dusuyordu). Bu yuzden jk korunuyor.
const normUrl = (u) => {
  const s = String(u || '').trim().toLowerCase();
  const m = s.match(/[?&]jk=([a-z0-9]+)/);
  const base = s.split('?')[0].replace(/\/+$/, '');
  return m ? base + '?jk=' + m[1] : base;
};

// --- basvurulanlarin indeksi ---
// Basvuru e-Tablosunun sutun ADLARI degisebilir (Position -> Title gibi).
// Bu yuzden sabit anahtar yerine BUYUK/kucuk harf ve bosluk duyarsiz arama yapiyoruz.
// Bir sutun bulunamazsa sessizce bos kalmasin diye asagida uyari basiliyor.
const pick = (obj, names) => {
  const lower = {};
  for (const k of Object.keys(obj)) lower[String(k).trim().toLowerCase()] = obj[k];
  for (const n of names) {
    const v = lower[n];
    if (v != null && String(v).trim()) return String(v).trim();
  }
  return '';
};
const COMPANY_COLS  = ['company', 'firma', 'arbeitgeber', 'sirket'];
const POSITION_COLS = ['title', 'position', 'job title', 'jobtitle', 'stelle', 'pozisyon'];
const LINK_COLS     = ['link', 'url', 'job url', 'joburl', 'ilan linki'];
const DATE_COLS    = ['application date', 'applied at', 'applied on', 'date',
                      'tarih', 'basvuru tarihi'];

// --- SADECE SON 2 AY: eski basvurular kapiyi kapatmasin ---
// Cok eski bir basvuru artik ilani bloklamamali; o sirket/pozisyon tekrar acildiysa
// yeniden degerlendirilsin. Tarihi okunamayan satir GUVENLI tarafta kalir (kapida durur).
const APPLIED_WINDOW_DAYS = 60;
const CUTOFF = new Date(Date.now() - APPLIED_WINDOW_DAYS * 86400000);

// Basvuru sayfasindaki tarihler nokta ayracli ve AY.GUN.YIL sirasinda (orn 08.06.2026 =
// 6 Agustos). Yine de sira karisirsa diye: bir alan 12'yi asiyorsa o alan GUN kabul edilir.
function parseAppliedDate(raw) {
  const s = String(raw == null ? '' : raw).trim();
  if (!s) return null;

  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);            // ISO
  if (m) return new Date(+m[1], +m[2] - 1, +m[3]);

  m = s.match(/^(\d{1,2})[.\/-](\d{1,2})[.\/-](\d{4})/);      // AY.GUN.YIL / GUN.AY.YIL
  if (m) {
    const a = +m[1], b = +m[2];
    let month, day;
    if (a > 12)      { day = a; month = b; }   // ilk alan gun olmak zorunda
    else if (b > 12) { month = a; day = b; }   // ikinci alan gun olmak zorunda
    else             { month = a; day = b; }   // belirsiz -> sayfadaki hakim duzen: AY.GUN
    if (month < 1 || month > 12 || day < 1 || day > 31) return null;
    return new Date(+m[3], month - 1, day);
  }

  if (/^\d+(\.\d+)?$/.test(s)) {                              // Sheets seri numarasi
    const d = new Date(Date.UTC(1899, 11, 30) + Math.floor(+s) * 86400000);
    return isNaN(d) ? null : d;
  }

  const d = new Date(s);
  return isNaN(d) ? null : d;
}

const appliedKeys = new Set();
const appliedUrls = new Set();
let noCompany = 0, noPosition = 0, tooOld = 0, noDate = 0;
for (const r of appliedRows) {
  const j = r.json || {};

  // pencere disindaki basvurular indekse hic girmez
  const applied = parseAppliedDate(pick(j, DATE_COLS));
  if (applied === null) noDate++;                  // tarih yok -> guvenli taraf, kapida kalir
  else if (applied < CUTOFF) { tooOld++; continue; }

  const company  = pick(j, COMPANY_COLS);
  const position = pick(j, POSITION_COLS);
  const link     = pick(j, LINK_COLS);
  if (!company)  noCompany++;
  if (!position) noPosition++;
  if (company && position) appliedKeys.add(key(company, position));
  if (link) appliedUrls.add(normUrl(link));
}
if (appliedRows.length && (noCompany || noPosition)) {
  console.log(`UYARI: basvuru sayfasinda ${noCompany} satirda sirket, ${noPosition} satirda ` +
              `pozisyon sutunu bulunamadi -> o satirlar sadece URL ile eslesir. ` +
              `Beklenen basliklar: ${COMPANY_COLS[0]} / ${POSITION_COLS.join(' | ')}`);
}

const kept = [];
let byKey = 0, byUrl = 0;
for (const it of incoming) {
  const j = it.json;
  const k = key(j.company, j.title);
  const u = normUrl(j.url);
  if (appliedKeys.has(k)) { byKey++; continue; }
  if (u && appliedUrls.has(u)) { byUrl++; continue; }
  kept.push(it);
}

const cutStr = CUTOFF.toISOString().slice(0, 10);
console.log(`Applied gate: ${appliedRows.length} basvuru -> ${appliedRows.length - tooOld} tanesi son ` +
            `${APPLIED_WINDOW_DAYS} gun icinde (${cutStr} sonrasi); ${tooOld} eski basvuru yok sayildi` +
            (noDate ? `, ${noDate} satirda tarih okunamadi (kapida birakildi)` : '') + '.');
console.log(`Applied gate: gelen ${incoming.length} -> kalan ${kept.length} (elenen: ${byKey} anahtar, ${byUrl} url)`);
return kept;

// AYNI ILAN, FARKLI SEHIR -> EN IYI SEHRI TUT.
// dedup_key sehirsizdir (bilerek): ayni ilani farkli kaynaklardan birlestirir.
// Ama "ilk geleni tut" davranisi, hangi kaynagin Merge'e once bagli oldugunu
// takip eder — yani Berlin ilani, sirf Adzuna input[0]'da diye Munih'e yenilebilir.
// Burada bunun yerine TERCIH SIRASINA gore sececegiz: skor da link de dogru sehirden gelsin.
const items = $input.all();

// Score Location & Language ile ayni sira. Kucuk rank = daha iyi.
const CITY_RANK = ['berlin', 'munich', 'hamburg'];

const normCity = (s) => {
  let v = String(s == null ? '' : s).trim();
  if (v.startsWith('{')) {                       // bazi kaynaklar JSON blob gonderiyor
    try { const o = JSON.parse(v); v = o.locality || o.raw || v; } catch (e) {}
  }
  return v.toLowerCase()
    .replace(/ü/g, 'u').replace(/ö/g, 'o').replace(/ä/g, 'a').replace(/ß/g, 'ss')
    .replace(/muenchen|munchen/g, 'munich')
    .replace(/[^a-z ]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
};

const rank = (item) => {
  const c = normCity(item.json.city || item.json.location_raw);
  if (!c) return CITY_RANK.length + 1;           // sehir bilinmiyor -> en sona
  for (let i = 0; i < CITY_RANK.length; i++) {
    if (c.includes(CITY_RANK[i])) return i;
  }
  return CITY_RANK.length;                       // Almanya'da baska sehir
};

// Sehir esitse EN UZUN aciklamayi tut: ayni ilan Adzuna'dan 500 karakterlik kirpik
// metinle, XING'den 3-7 bin karakterlik tam metinle geliyordu ve hangisinin kaldigi
// Merge sirasina bakiyordu. Kirpik kopya kalinca model ilani okumadan puanliyor.
const descLen = (it) => String((it.json && it.json.description) || '').length;

const best = new Map();
for (const it of items) {
  const k = it.json.dedup_key;
  if (k == null) continue;
  const cur = best.get(k);
  if (!cur) { best.set(k, it); continue; }
  const dr = rank(it) - rank(cur);
  // Once sehir (kucuk rank kazanir), sehir esitse daha dolu metin kazanir.
  // Esitlikte ILK gelen kalir -> mevcut davranis korunur.
  if (dr < 0 || (dr === 0 && descLen(it) > descLen(cur))) best.set(k, it);
}

const out = [...best.values()];

// ne kazandik: sadece sehir farkiyla elenen ve DAHA IYI sehri secilen ilanlar
let upgraded = 0;   // sehir VEYA metin uzunlugu yuzunden
const firstSeen = new Map();
for (const it of items) {
  const k = it.json.dedup_key;
  if (k != null && !firstSeen.has(k)) firstSeen.set(k, it);
}
for (const [k, chosen] of best) {
  const first = firstSeen.get(k);
  if (first && first !== chosen) upgraded++;
}

console.log(`Best-city dedup: ${items.length} -> ${out.length} (sehir yuzunden yukseltilen: ${upgraded})`);
return out;

