//   2) KUYRUK KESME — "Jetzt bewerben" / "Ansprechpartner" gibi basvuru bloklari
//                    pratikte hep en sondadir; oradan metnin sonuna kadar kes.
//   3) KLISE CUMLE  — tek cumlelik yasal metinler (Schwerbehinderte, equal opportunity).
// GUVENLIK FRENI: metin %70'ten fazla kisalirsa yanlis yerden kesmisizdir -> geri al.
const items = $input.all();

// SADECE yan haklar. Sirket tanitimi ("Über uns", "Why join") BILEREK haric:
// sektor, urun ve buyukluk CV uyumu icin sinyaldir ve company_brief alanini besler.
// Rol tanimi, gorevler ve gereksinimler hicbir kosulda silinmez.
const BENEFIT_HEADS = /^(wir bieten|das bieten wir|was wir (dir |ihnen )?bieten|unsere benefits|deine (vorteile|benefits)|ihre vorteile|benefits|perks|what we offer)\b/i;

const APPLY_HEADS = /^(jetzt (online )?bewerben|online bewerben|wir freuen uns|interessiert|neugierig geworden|haben wir dein interesse|klingt (das )?nach dir|werde teil|(deine|ihre) bewerbung|bewerbungsprozess|(dein|ihr) ansprechpartner|ansprechpartner|kontakt|so bewirbst du dich|how to apply|ready to apply|apply now|sound like you|our hiring process|what happens next|next steps)\b/i;

const CLICHE = [
  /schwerbehinderte[^.\n]*(bevorzugt|gleicher eignung|berücksichtigt)[^.\n]*\.?/gi,
  /wir setzen uns für (chancengleichheit|vielfalt)[^.\n]*\.?/gi,
  /unabhängig von (geschlecht|alter|herkunft|religion|nationalität)[^.\n]*\.?/gi,
  /we are an equal opportunit[^.\n]*\.?/gi,
  /regardless of (race|gender|age|religion)[^.\n]*\.?/gi,
  /all qualified applicants[^.\n]*\.?/gi,
];

// Baslik mi? Kisa, madde isareti yok, ve ya ":" ile biter ya da cok kisa bir satirdir.
function isHeading(line) {
  const s = line.trim();
  if (!s || s.length > 70) return false;
  if (/^[-*\u2022\d]/.test(s)) return false;      // madde -> baslik degil
  return s.endsWith(':') || s.length <= 40;
}

function trim(text) {
  const original = String(text || '');
  if (original.length < 400) return original;     // zaten kisa
  const lines = original.split('\n');
  const keep = [];
  let skipping = false;
  // Kuyruk kesme yalnizca ilanin ARKA YARISINDA tetiklenebilir. Boylece ortada gecen
  // bir "Kontakt" basligi, altindaki gereksinimleri ucuramaz.
  const cutFloor = Math.floor(lines.length / 2);

  for (let li = 0; li < lines.length; li++) {
    const line = lines[li];
    const s = line.trim();
    if (isHeading(s)) {
      const head = s.replace(/[:：]\s*$/, '');
      if (APPLY_HEADS.test(head) && li >= cutFloor) break;   // kuyruk: sonrasi gitsin
      skipping = BENEFIT_HEADS.test(head);        // bolum: sonraki basliga kadar atla
      if (skipping) continue;
    }
    if (!skipping) keep.push(line);
  }

  let t = keep.join('\n');
  for (const rx of CLICHE) t = t.replace(rx, ' ');
  t = t.replace(/[ \t]{2,}/g, ' ').replace(/\n{3,}/g, '\n\n').trim();

  if (t.length < original.length * 0.30) return original;   // guvenlik freni
  return t;
}

let before = 0, after = 0, touched = 0;
const out = items.map(it => {
  const d = it.json.description || '';
  const cleaned = trim(d);
  before += d.length; after += cleaned.length;
  if (cleaned.length !== d.length) touched++;
  return { json: { ...it.json, description: cleaned } };
});

const pct = before ? Math.round((1 - after / before) * 100) : 0;
console.log(`JD trim: ${items.length} ilan · ${before} -> ${after} karakter (-${pct}%) · degisen: ${touched}`);
return out;

