// KONUM METNI — e-Tabloya HER ZAMAN okunabilir bir ad yaz, asla JSON blob'u yazma.
// 2026-08-26'da bulundu: 3.701 satirin 851'i (%23) su sekilde yazilmis:
//   {"raw":"Berlin, Germany","locality":"Berlin","country":"Germany","country_code":"DE"}
// Kaynak eski agentx donemi (linkedin 746 + indeed 105, 13-25 Agustos). Yeni
// `LinkedIn DE Fields` duz metin uretiyor, ama koruma TEK NOKTADA burada duruyor ki
// hangi kaynak ne gonderirse gondersin sutun okunabilir kalsin.
// Cikti tercihi: "Sehir, Ulke" -> yoksa sehir -> yoksa bolge -> yoksa ulke -> yoksa ham metin.
const prettyLocation = (v) => {
  if (v == null) return '';
  let o = v;
  if (typeof o === 'string') {
    const s = o.trim();
    if (!s.startsWith('{')) return s;          // zaten duz metin
    try { o = JSON.parse(s); } catch (e) { return s; }
  }
  if (typeof o !== 'object') return String(o);
  const pick = (k) => String(o[k] == null ? '' : o[k]).trim();
  const loc = pick('locality') || pick('city');
  const reg = pick('region');
  const ctry = pick('country');
  if (loc && ctry && loc.toLowerCase() !== ctry.toLowerCase()) return loc + ', ' + ctry;
  return loc || reg || ctry || pick('raw') || pick('formatted');
};

